const app = document.querySelector("#app");
const state = { me:null, dashboard:null, clients:[], reminders:[], staff:[], documents:[], invitations:[], forms:[], formImports:[], dailyStatus:[], reviewRequests:[], shiftSettings:null, session:null, plan:null, client:null, targetForm:null, preview:false, selectedSuggestedForms:[], selectedSuggestionSession:null, pendingCareMinutes:"" };
const CADENCE_LABELS = {daily:"Dagelijks", incident:"Bij incident", on_demand:"Op aanvraag", disabled:"Uit"};
const esc = value => String(value ?? "").replace(/[&<>\"]/g, c => ({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
const fmt = value => new Intl.DateTimeFormat("nl-NL", {day:"2-digit",month:"short",hour:"2-digit",minute:"2-digit"}).format(new Date(value));
new MutationObserver(()=>{const minutes=document.querySelector("#minutes");if(minutes&&state.pendingCareMinutes&&!minutes.value)minutes.value=state.pendingCareMinutes;}).observe(app,{childList:true,subtree:true});

async function api(path, options={}) {
  const headers = options.body instanceof FormData ? {} : {"Content-Type":"application/json"};
  const response = await fetch(path, {credentials:"same-origin", ...options, headers:{...headers,...(options.headers||{})}});
  const data = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(typeof data.detail==="object"?(data.detail.message||"Er ging iets mis"):(data.detail||"Er ging iets mis"));
  return data;
}

function shell(content, title="ZorgVerhaal AI") {
  window.scrollTo({top:0,left:0,behavior:"instant"});
  app.innerHTML = `<div class="ribbon">FICTIEVE DEMO · GEBRUIK GEEN ECHTE CLIËNTGEGEVENS</div><main><header><b class="logo">Z</b><strong>${esc(title)}</strong><button class="headlink" id="home">⌂</button></header><div class="error-slot"></div>${content}</main>`;
  document.querySelector("#home")?.addEventListener("click", routeHome);
  if(title==="Organisatiebeheer" && state.me?.role==="org_admin" && document.querySelector(".pad")) {
    document.querySelector(".pad").insertAdjacentHTML("beforeend",`<button class="secondary" id="formImports">Formulieren slim importeren</button>`);
    document.querySelector(".pad").insertAdjacentHTML("beforeend",`<button class="secondary" id="shiftSettings">Diensten en overdracht instellen</button>`);
    document.querySelector("#formImports").onclick=formImportsPage;
    document.querySelector("#shiftSettings").onclick=shiftSettingsPage;
  }
  if((title==="Vandaag" || title==="Medewerkersdemo") && state.dailyStatus?.length) {
    const byClient=Object.fromEntries(state.dailyStatus.map(item=>[item.client_id,item]));
    document.querySelectorAll("button[data-client]").forEach(button=>{const item=byClient[button.dataset.client];if(!item)return;const completed=item.required.filter(form=>item.completed_form_types.includes(form.form_type)).length;button.querySelector("div")?.insertAdjacentHTML("beforeend",`<small class="dailyprogress ${item.complete?"complete":"pending"}">${item.complete?"Dagelijkse formulieren compleet":`${completed}/${item.required.length} dagelijkse formulieren gereed`}</small>`)});
  }
}
function showError(error) { const slot=document.querySelector(".error-slot"); if(slot) slot.innerHTML=`<div class="error">${esc(error.message)}</div>`; }
function busy(button, label="Even wachten…") { button.disabled=true; button.dataset.old=button.textContent; button.textContent=label; }

async function boot() {
  const joinToken = new URLSearchParams(location.search).get("join");
  if (joinToken) return joinPage(joinToken);
  try {
    state.me = await api("/api/me");
    state.dashboard = await api("/api/dashboard");
    state.preview = new URLSearchParams(location.search).get("demo") === "employee" && state.me.role === "org_admin";
    routeHome();
  } catch { loginPage(); }
}

function loginPage() {
  shell(`<section class="pad login"><p class="eyebrow">BEVEILIGDE DEMO</p><h1>Inloggen</h1><p class="lead">Je dashboard wordt bepaald door je rol.</p><form id="login"><label>E-mailadres<input name="email" type="email" required></label><label>Wachtwoord<input name="password" type="password" required></label><button>Inloggen</button></form></section>`);
  document.querySelector("#home").hidden=true;
  document.querySelector("#login").onsubmit=async e=>{e.preventDefault();const button=e.submitter;busy(button,"Inloggen…");try{await api("/api/login",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});history.replaceState({},"","/");await boot()}catch(x){showError(x);button.disabled=false;button.textContent=button.dataset.old}};
}

async function joinPage(token) {
  try {
    const info=await api(`/api/join/${token}`);
    shell(`<section class="pad login joincard"><p class="eyebrow">UITNODIGING VAN ${esc(info.organization).toUpperCase()}</p><h1>Activeer je medewerkersaccount</h1><p class="lead">Welkom${info.employee_name?`, ${esc(info.employee_name)}`:""}. Maak één keer je account aan; daarna log je altijd in met je eigen e-mailadres en wachtwoord.</p><div class="identitycard"><span>${initials(info.employee_name||"Nieuwe medewerker")}</span><div><b>${esc(info.employee_name||"Nieuwe medewerker")}</b><small>Medewerkernummer ${esc(info.employee_number||"wordt toegewezen")}</small></div></div><form id="join"><label>Volledige naam<input name="name" value="${esc(info.employee_name||"")}" required></label><label>Werk-e-mailadres<input name="email" type="email" value="${esc(info.intended_email||"")}" ${info.intended_email?"readonly":""} required></label><label>Kies een wachtwoord<input name="password" type="password" minlength="12" autocomplete="new-password" required><small>Minimaal 12 tekens.</small></label><button>Account activeren</button></form><p class="privacy">Na activatie kom je direct in je eigen werkomgeving.</p></section>`,"Welkom");
    document.querySelector("#home").hidden=true;
    document.querySelector("#join").onsubmit=async e=>{e.preventDefault();try{await api(`/api/join/${token}`,{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});history.replaceState({},"","/");await boot()}catch(x){showError(x)}};
  } catch(x) { shell(`<section class="pad"><h1>Link niet bruikbaar</h1><p class="lead">${esc(x.message)}</p></section>`); }
}

function routeHome() {
  if (state.preview || state.me.role === "caregiver") return workerDashboard();
  if (state.me.role === "platform_admin") return platformDashboard();
  return organizationDashboard();
}

async function platformDashboard() {
  try {
    const [orgs,docs]=await Promise.all([api("/api/platform/organizations"),api("/api/platform/documents")]);
    shell(`<section class="pad"><p class="eyebrow">PRIVÉ PLATFORMBEHEER</p><h1>Goedemorgen, Ruard</h1><div class="metrics"><article><b>${orgs.length}</b><span>Zorgaanbieders</span></article><article class="warn"><b>${docs.filter(d=>["uploaded","reviewing"].includes(d.status)).length}</b><span>Documenten vragen actie</span></article></div><button id="newOrg">＋ Zorgaanbieder toevoegen</button><h2>Document-inbox</h2>${docs.length?docs.map(documentCard).join(""):`<p class="muted">Nog geen documenten geüpload.</p>`}<h2>Organisaties</h2>${orgs.map(o=>`<article class="listcard"><div><b>${esc(o.name)}</b><small>${o.staff} gebruikers · ${o.documents} documenten</small></div><span>›</span></article>`).join("")||`<p class="muted">Maak de eerste demo-organisatie aan.</p>`}<button class="secondary" id="logout">Uitloggen</button></section>`,"Platformadmin");
    document.querySelector("#newOrg").onclick=newOrganization;
    document.querySelector("#logout").onclick=logout;
    document.querySelectorAll("[data-doc-status]").forEach(b=>b.onclick=()=>updateDocument(b.dataset.docStatus,b.dataset.id));
  } catch(x){showError(x)}
}
function documentCard(d){return `<article class="doccard"><div class="status ${esc(d.status)}">${statusLabel(d.status)}</div><b>${esc(d.organization)}</b><p>${esc(d.file_name)}</p><small>${esc(d.note||"Geen toelichting")}</small>${d.admin_note?`<div class="adminnote">${esc(d.admin_note)}</div>`:""}<div class="row"><a class="smallbtn" href="/api/platform/documents/${d.id}/download">Download</a><button class="smallbtn" data-doc-status="reviewing" data-id="${d.id}">In behandeling</button><button class="smallbtn" data-doc-status="concept_ready" data-id="${d.id}">Concept klaar</button></div></article>`}
const statusLabel=s=>({uploaded:"Nieuw",reviewing:"In behandeling",concept_ready:"Concept klaar",client_review:"Controle organisatie",active:"Actief"}[s]||s);
function shiftSettingsPage(){
  const shifts=state.shiftSettings?.shifts||[];
  const row=(s={name:"",starts_at:"",minimum_handover:""})=>`<article class="shiftrow"><label>Dienstnaam<input data-shift-name value="${esc(s.name)}" required></label><label>Begint om<input data-shift-start type="time" value="${esc(s.starts_at)}" required></label><label>Wat moet deze dienst minimaal doen en vastleggen?<textarea data-shift-min>${esc(s.minimum_handover)}</textarea></label><button type="button" class="tiny removeShift">Verwijderen</button></article>`;
  shell(`<section class="pad"><button class="back" id="back">‹</button><p class="eyebrow">ORGANISATIE-INSTELLING</p><h1>Diensten en minimumeisen</h1><p class="lead">Bepaal zelf hoeveel diensten er zijn, in welke volgorde ze starten en wat elke dienst minimaal moet doen en vastleggen. De app kiest automatisch de huidige en volgende dienst.</p><form id="shiftForm"><div id="shiftRows">${shifts.map(row).join("")}</div><button type="button" class="secondary" id="addShift">Dienst toevoegen</button><button>Instellingen opslaan</button></form></section>`,"Diensten instellen");
  document.querySelector("#back").onclick=organizationDashboard;
  const bindRemove=()=>document.querySelectorAll(".removeShift").forEach(b=>b.onclick=()=>b.closest(".shiftrow").remove());bindRemove();
  document.querySelector("#addShift").onclick=()=>{document.querySelector("#shiftRows").insertAdjacentHTML("beforeend",row());bindRemove()};
  document.querySelector("#shiftForm").onsubmit=async e=>{e.preventDefault();const values=[...document.querySelectorAll(".shiftrow")].map(r=>({name:r.querySelector("[data-shift-name]").value.trim(),starts_at:r.querySelector("[data-shift-start]").value,minimum_handover:r.querySelector("[data-shift-min]").value.trim()}));if(!values.length)return showError(new Error("Voeg minimaal één dienst toe"));try{await api("/api/organization/shifts",{method:"POST",body:JSON.stringify({shifts:values})});organizationDashboard()}catch(x){showError(x)}};
}
async function formImportsPage(){
  try{state.formImports=await api("/api/organization/form-imports");if(!state.documents.length)state.documents=await api("/api/organization/documents");
  const draftByDocument=Object.fromEntries(state.formImports.map(item=>[item.document_id,item]));
  shell(`<section class="pad"><button class="back" id="back">‹</button><p class="eyebrow">SOL · EENMALIGE FORMULIERANALYSE</p><h1>Formulieren slim importeren</h1><p class="lead">Sol neemt velden, volgorde en antwoordopties uit PDF, DOCX, TXT of JSON over. Er wordt niets actief totdat jij het concept met het origineel hebt vergeleken.</p>${state.documents.map(document=>{const draft=draftByDocument[document.id];return `<article class="doccard"><b>${esc(document.file_name)}</b><small>${draft?`Import: ${esc(draft.status)}`:"Nog niet geanalyseerd"}</small>${draft?`<button class="smallbtn" data-review-import="${draft.id}">Concept controleren</button>`:`<button class="smallbtn" data-analyze-document="${document.id}">Analyseren met Sol</button>`}</article>`}).join("")||`<div class="notice">Upload eerst een formulier via Document uploaden.</div>`}</section>`,"Formulieren importeren");
  document.querySelector("#back").onclick=organizationDashboard;
  document.querySelectorAll("[data-review-import]").forEach(button=>button.onclick=()=>formImportReviewPage(state.formImports.find(item=>item.id===button.dataset.reviewImport)));
  document.querySelectorAll("[data-analyze-document]").forEach(button=>button.onclick=async()=>{busy(button,"Sol leest het formulier…");try{const result=await api(`/api/organization/documents/${button.dataset.analyzeDocument}/analyze-form`,{method:"POST"});const item={id:result.import_id,document_id:button.dataset.analyzeDocument,status:"concept",proposal:result.proposal,telemetry:result.telemetry};state.formImports.unshift(item);formImportReviewPage(item)}catch(x){showError(x);button.disabled=false;button.textContent=button.dataset.old}});
  }catch(x){showError(x)}
}
function formImportReviewPage(item){
  const proposal=item.proposal;const field=(value)=>esc(value||"");
  shell(`<section class="pad"><button class="back" id="back">‹</button><p class="eyebrow">MENSELIJKE BRONCONTROLE</p><h1>Controleer het formulierconcept</h1><div class="notice"><b>Niet automatisch activeren</b><p>Vergelijk ieder label, iedere optie, volgorde en verplichting met het originele document. Pas alleen aan naar de letterlijke brontekst.</p></div><form id="importReview"><label>Formuliertitel<input id="importTitle" value="${field(proposal.title)}" required></label><label>Technisch formuliertype<input id="importType" value="${field(proposal.suggested_form_type)}" pattern="[a-z0-9_]+" required></label><label>Wanneer gebruiken?<select id="importCadence"><option value="daily" ${proposal.suggested_cadence==="daily"?"selected":""}>Dagelijks, voor iedere cliënt</option><option value="incident" ${proposal.suggested_cadence==="incident"?"selected":""}>Bij relevant incident</option><option value="on_demand" ${proposal.suggested_cadence==="on_demand"?"selected":""}>Op aanvraag</option></select></label>${proposal.uncertainties?.length?`<div class="alert attention"><b>Controlepunten van Sol</b>${proposal.uncertainties.map(value=>`<p>${esc(value)}</p>`).join("")}</div>`:""}<div id="importSections">${proposal.sections.map((section,sectionIndex)=>`<article class="formsection importsection" data-section="${sectionIndex}"><label>Sectietitel<input data-section-title value="${field(section.title)}"></label>${section.fields.map(formField=>`<div class="importfield"><label>Veldlabel<input data-import-label value="${field(formField.label)}" required></label><input type="hidden" data-import-id value="${field(formField.id)}"><label>Type<select data-import-type>${["text","textarea","select","multiselect","boolean","date","datetime","number"].map(type=>`<option ${formField.type===type?"selected":""}>${type}</option>`).join("")}</select></label><label>Antwoordopties, één per regel<textarea data-import-options>${field((formField.options||[]).join("\n"))}</textarea></label><label class="minicheck"><input data-import-required type="checkbox" ${formField.required?"checked":""}><span>Verplicht volgens bron</span></label><div class="sourcequote"><b>Letterlijk bronfragment</b><p>${esc(formField.source_quote)}</p><input type="hidden" data-source-quote value="${field(formField.source_quote)}"></div></div>`).join("")}</article>`).join("")}</div><label class="check"><input id="importAck" type="checkbox"><span><b>Ik heb dit concept veld voor veld met het origineel vergeleken</b><small>Activeren kan pas na deze controle. De server controleert labels, opties en bronfragmenten opnieuw.</small></span></label><button>Identiek gecontroleerd en activeren</button></form></section>`,"Formulier controleren");
  document.querySelector("#back").onclick=formImportsPage;
  document.querySelector("#importReview").onsubmit=async event=>{event.preventDefault();if(!document.querySelector("#importAck").checked)return showError(new Error("Bevestig eerst de vergelijking met het origineel"));const sections=[...document.querySelectorAll(".importsection")].map(section=>({title:section.querySelector("[data-section-title]").value,fields:[...section.querySelectorAll(".importfield")].map(row=>({id:row.querySelector("[data-import-id]").value,label:row.querySelector("[data-import-label]").value,type:row.querySelector("[data-import-type]").value,required:row.querySelector("[data-import-required]").checked,options:row.querySelector("[data-import-options]").value.split("\n").map(value=>value.trim()).filter(Boolean),source_quote:row.querySelector("[data-source-quote]").value}))}));const updated={...proposal,title:document.querySelector("#importTitle").value,suggested_form_type:document.querySelector("#importType").value,suggested_cadence:document.querySelector("#importCadence").value,sections};const button=event.submitter;busy(button,"Brongetrouwheid controleren…");try{await api(`/api/organization/form-imports/${item.id}/activate`,{method:"POST",body:JSON.stringify({proposal:updated,human_review_confirmed:true})});organizationDashboard()}catch(x){showError(x);button.disabled=false;button.textContent=button.dataset.old}};
}
function newOrganization(){shell(`<section class="pad"><button class="back" id="back">‹</button><p class="eyebrow">NIEUWE KLANTDEMO</p><h1>Zorgaanbieder toevoegen</h1><form id="org"><label>Organisatienaam<input name="name" required></label><label>E-mailadres beheerder<input name="admin_email" type="email" required></label><label>Tijdelijk wachtwoord<input name="admin_password" minlength="12" required></label><button>Aanmaken</button></form></section>`,"Platformadmin");document.querySelector("#back").onclick=platformDashboard;document.querySelector("#org").onsubmit=async e=>{e.preventDefault();try{await api("/api/platform/organizations",{method:"POST",body:JSON.stringify(Object.fromEntries(new FormData(e.target)))});platformDashboard()}catch(x){showError(x)}}}
async function updateDocument(status,id){const note=prompt("Korte terugkoppeling voor de zorgaanbieder:","")??"";try{await api(`/api/platform/documents/${id}/status`,{method:"POST",body:JSON.stringify({status,admin_note:note})});platformDashboard()}catch(x){showError(x)}}

async function organizationManagementPage() {
  try {
    [state.clients,state.reminders,state.staff,state.documents,state.invitations,state.forms,state.shiftSettings]=await Promise.all([api("/api/clients"),api("/api/reminders"),api("/api/organization/staff"),api("/api/organization/documents"),api("/api/organization/invitations"),api("/api/organization/forms").catch(()=>[]),api("/api/organization/shifts")]);
    const activeInvites=state.invitations.filter(i=>!i.revoked&&!i.expired);
    shell(`<section class="pad"><p class="eyebrow">ZORGAANBIEDER</p><h1>${esc(state.dashboard.organization)}</h1><div class="metrics"><article><b>${state.clients.length}</b><span>Cliënten</span></article><article><b>${state.staff.length}</b><span>Medewerkers</span></article><article><b>${state.reminders.length}</b><span>Open acties</span></article></div>${!state.clients.length?`<div class="notice"><b>Maak de fictieve demo gereed</b><p>Voegt drie cliënten, zorgdoelen, reminders en het basisformulier toe.</p><button id="seed">Demo-inhoud toevoegen</button></div>`:""}<button id="workerDemo">▶ Bekijk medewerkersdemo</button><div class="actiongrid"><button class="secondary" id="invite">Medewerker uitnodigen</button><button class="secondary" id="upload">Document uploaden</button><button class="secondary" id="addClient">Cliënt toevoegen</button><button class="secondary" id="addReminder">Reminder toevoegen</button></div>${activeInvites.length?`<h2>Actieve uitnodigingslinks</h2>${activeInvites.map(i=>`<article class="listcard"><div><b>Medewerkerslink</b><small>${i.uses}/${i.max_uses} gebruikt · geldig tot ${fmt(i.expires_at)}</small></div><button class="tiny" data-revoke="${i.id}">Intrekken</button></article>`).join("")}`:""}<h2>Documenten voor Ruard</h2>${state.documents.map(d=>`<article class="listcard"><div><b>${esc(d.file_name)}</b><small>${statusLabel(d.status)}${d.admin_note?` · ${esc(d.admin_note)}`:""}</small></div></article>`).join("")||`<p class="muted">Nog niets geüpload.</p>`}${state.forms.length?`<h2>Formulieren</h2><p class="muted">Bepaal per formulier wanneer medewerkers het gebruiken: dagelijks, alleen bij een incident, op aanvraag, of uit.</p>${state.forms.map(formCadenceCard).join("")}`:""}<h2>Medewerkers en cliënten</h2>${state.staff.map(staffCard).join("")}<h2>Actieve zorgdoelen</h2>${state.clients.map(c=>`<article class="clientcard"><div class="clienthead"><b>${esc(c.display_name)}</b><button class="tiny archive" data-archive="${c.id}">Archiveren</button></div>${c.goals.map(g=>`<span class="goal">◎ ${esc(g.title)}</span>`).join("")}</article>`).join("")}<button class="dangerlink" id="reset">Fictieve demo-inhoud resetten</button><button class="secondary" id="logout">Uitloggen</button></section>`,"Organisatiebeheer");
    document.querySelector("#seed")?.addEventListener("click",seedDemo);document.querySelector("#workerDemo").onclick=()=>{state.preview=true;history.replaceState({},"","/?demo=employee");workerDashboard()};document.querySelector("#invite").onclick=createInvite;document.querySelector("#upload").onclick=uploadPage;document.querySelector("#addClient").onclick=addClientPage;document.querySelector("#addReminder").onclick=addReminderPage;document.querySelector("#logout").onclick=logout;document.querySelector("#reset").onclick=resetDemo;document.querySelectorAll("[data-assign]").forEach(b=>b.onclick=()=>assignPage(b.dataset.assign));document.querySelectorAll("[data-revoke]").forEach(b=>b.onclick=()=>revokeInvite(b.dataset.revoke));document.querySelectorAll("[data-archive]").forEach(b=>b.onclick=()=>archiveClient(b.dataset.archive));document.querySelectorAll(".cadence").forEach(s=>s.onchange=async()=>{const old=s.dataset.prev??s.value;try{await api(`/api/organization/forms/${s.dataset.form}/cadence`,{method:"POST",body:JSON.stringify({cadence:s.value})});s.dataset.prev=s.value}catch(x){s.value=old;showError(x)}});
    document.querySelector(".pad")?.insertAdjacentHTML("afterbegin",orgNav("management"));bindOrgNav();
  } catch(x){showError(x)}
}
function orgNav(active){const items=[["overview","Overzicht"],["clients","Cliënten"],["reviews","Controle"],["management","Beheer"],["audit","Audit"]];return `<nav class="orgnav">${items.map(([id,label])=>`<button class="${active===id?"active":""}" data-org-page="${id}">${label}</button>`).join("")}</nav>`}
function bindOrgNav(){document.querySelectorAll("[data-org-page]").forEach(button=>button.onclick=()=>({overview:organizationDashboard,clients:organizationClientsPage,reviews:organizationReviewsPage,management:organizationManagementPage,audit:organizationAuditPage}[button.dataset.orgPage]()))}
async function organizationDashboard(){
  try{const workspace=await api("/api/organization/workspace");state.orgWorkspace=workspace;shell(`<section class="pad orgshell">${orgNav("overview")}<div class="orgtitle"><div><p class="eyebrow">WERKGEVERSDOSSIER</p><h1>Goedemiddag</h1><p class="lead">Wat vandaag aandacht vraagt, zonder dossierinformatie te wijzigen.</p></div></div><div class="metrics"><article><b>${workspace.metrics.reports_today}</b><span>Rapportages vandaag</span></article><article><b>${workspace.metrics.open_questions}</b><span>Open aanvullingen</span></article><article><b>${workspace.metrics.answers_to_review}</b><span>Te beoordelen</span></article></div><section class="workpanel"><div class="sectionhead"><h2>Werkvoorraad</h2><button class="tiny" id="allReviews">Alles bekijken</button></div>${workspace.reviews.length?workspace.reviews.slice(0,6).map(reviewRow).join(""):`<p class="emptystate">Geen openstaande controlevragen.</p>`}</section><section class="workpanel"><div class="sectionhead"><h2>Recente dossieractiviteit</h2><button class="tiny" id="allClients">Naar cliënten</button></div>${workspace.recent_reports.slice(0,8).map(reportRow).join("")||`<p class="emptystate">Nog geen definitieve rapportages.</p>`}</section></section>`,"Werkgeversportaal");bindOrgNav();document.querySelector("#allReviews").onclick=organizationReviewsPage;document.querySelector("#allClients").onclick=organizationClientsPage;document.querySelectorAll("[data-report]").forEach(button=>button.onclick=()=>organizationReportPage(button.dataset.report));}catch(error){showError(error)}}
function reportRow(report){return `<button class="workrow" data-report="${report.id}"><span class="recordicon">R</span><div><b>${esc(report.client_name)}</b><small>${fmt(report.signed_at)} · ${esc(report.author)}</small></div><i>›</i></button>`}
function reviewRow(review){const status=review.status==="answered"?"Antwoord ontvangen":"Wacht op medewerker";return `<button class="workrow" data-report="${review.report_id}"><span class="statusdot ${review.status}"></span><div><b>${esc(review.client_name)}</b><small>${status}${review.due_at?` · voor ${fmt(review.due_at)}`:""}</small><p>${esc(review.question)}</p></div><i>›</i></button>`}
async function organizationClientsPage(){try{state.clients=await api("/api/clients");shell(`<section class="pad orgshell">${orgNav("clients")}<p class="eyebrow">DOSSIERS</p><h1>Cliënten</h1><p class="lead">Open een cliënt voor de volledige chronologische historie.</p><div class="clienttable">${state.clients.map(client=>`<button class="workrow" data-org-client="${client.id}"><span class="avatar">${initials(client.display_name)}</span><div><b>${esc(client.display_name)}</b><small>${client.goals.length} actieve zorgdoelen</small></div><i>›</i></button>`).join("")||`<p class="emptystate">Geen actieve cliënten.</p>`}</div></section>`,"Cliëntdossiers");bindOrgNav();document.querySelectorAll("[data-org-client]").forEach(button=>button.onclick=()=>organizationClientTimelinePage(button.dataset.orgClient));}catch(error){showError(error)}}
async function organizationClientTimelinePage(id){try{const data=await api(`/api/organization/clients/${id}/timeline`);shell(`<section class="pad orgshell"><button class="back" id="back">‹</button><p class="eyebrow">CLIËNTDOSSIER</p><h1>${esc(data.client.display_name)}</h1>${data.client.context?`<p class="lead">${esc(data.client.context)}</p>`:""}<h2>Zorgdoelen</h2><div class="goalstrip">${data.client.goals.map(goal=>`<span>${esc(goal)}</span>`).join("")||"Geen actieve zorgdoelen"}</div><h2>Historie</h2><div class="timeline">${data.events.map(event=>`<button class="timelineevent" data-kind="${event.kind}" data-id="${event.id}" data-report="${event.report_id||""}"><time>${fmt(event.created_at)}</time><span></span><div><b>${esc(event.title)}</b><small>${esc(event.subtitle)}</small></div></button>`).join("")||`<p class="emptystate">Nog geen dossierhistorie.</p>`}</div></section>`,"Cliëntdossier");document.querySelector("#back").onclick=organizationClientsPage;document.querySelectorAll(".timelineevent").forEach(button=>button.onclick=()=>button.dataset.kind==="report"?organizationReportPage(button.dataset.id):button.dataset.kind==="addendum"?organizationReportPage(button.dataset.report):viewSubmissionPage(button.dataset.id));}catch(error){showError(error)}}
async function organizationReportPage(id){try{const report=await api(`/api/organization/reports/${id}`);shell(`<section class="pad orgshell"><button class="back" id="back">‹</button><div class="recordhead"><div><p class="eyebrow">DEFINITIEF · ${fmt(report.signed_at)}</p><h1>Rapportage ${esc(report.client_name)}</h1><p>${esc(report.author)}${report.care_minutes!=null?` · ${report.care_minutes} minuten`:""}</p></div><span class="locked">🔒 Onveranderlijk</span></div><article class="recordbody">${esc(report.report_text).replace(/\n/g,"<br>")}</article><section class="reviewhistory"><div class="sectionhead"><h2>Controle en aanvullingen</h2><button class="tiny" id="askAddition">Aanvulling vragen</button></div>${report.reviews.map(review=>`<article class="reviewitem"><div><b>${esc(review.question)}</b><small>${fmt(review.created_at)} · ${review.status==="open"?"open":review.status==="answered"?"antwoord ontvangen":"afgerond"}</small></div>${review.addendum?`<blockquote>${esc(review.addendum)}</blockquote>`:""}${review.status==="answered"?`<button class="tiny" data-close-review="${review.id}">Beoordeeld en afronden</button>`:""}</article>`).join("")||`<p class="emptystate">Geen controlevragen of aanvullingen.</p>`}</section><div class="integritynote"><b>Waarom niet wijzigen?</b><p>Dit verslag is definitief ondertekend. Nieuwe informatie wordt als gedateerde aanvulling opgeslagen, zodat zichtbaar blijft wie wat wanneer vastlegde.</p></div></section>`,"Dossierstuk");document.querySelector("#back").onclick=()=>organizationClientTimelinePage(report.client_id);document.querySelector("#askAddition").onclick=()=>requestAdditionPage(report);document.querySelectorAll("[data-close-review]").forEach(button=>button.onclick=async()=>{await api(`/api/organization/reviews/${button.dataset.closeReview}/close`,{method:"POST"});organizationReportPage(id)});}catch(error){showError(error)}}
function requestAdditionPage(report){shell(`<section class="pad orgshell"><button class="back" id="back">‹</button><p class="eyebrow">GERICHT TERUGVRAGEN</p><h1>Aanvulling vragen</h1><p class="lead">Het oorspronkelijke verslag blijft ongewijzigd. De auteur ontvangt één concrete vraag en diens antwoord wordt gekoppeld vastgelegd.</p><form id="additionRequest"><label>Wat moet worden verduidelijkt?<textarea name="question" required placeholder="Bijvoorbeeld: welk waarneembaar effect zag je na de interventie?"></textarea></label><label>Gewenst voor<input name="due_at" type="datetime-local"></label><button>Verzoek versturen</button></form></section>`,"Aanvulling vragen");document.querySelector("#back").onclick=()=>organizationReportPage(report.id);document.querySelector("#additionRequest").onsubmit=async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(event.target));values.due_at=values.due_at?new Date(values.due_at).toISOString():null;try{await api(`/api/organization/reports/${report.id}/request-addition`,{method:"POST",body:JSON.stringify(values)});organizationReportPage(report.id)}catch(error){showError(error)}}}
async function organizationReviewsPage(){try{const workspace=await api("/api/organization/workspace");shell(`<section class="pad orgshell">${orgNav("reviews")}<p class="eyebrow">KWALITEITSCONTROLE</p><h1>Controle en aanvullingen</h1><p class="lead">Gerichte vragen bij definitieve rapportages. Antwoorden worden als aanvulling vastgelegd.</p>${workspace.reviews.map(reviewRow).join("")||`<p class="emptystate">Geen openstaande vragen.</p>`}</section>`,"Controle");bindOrgNav();document.querySelectorAll("[data-report]").forEach(button=>button.onclick=()=>organizationReportPage(button.dataset.report));}catch(error){showError(error)}}
async function organizationAuditPage(){try{const rows=await api("/api/organization/audit");shell(`<section class="pad orgshell">${orgNav("audit")}<p class="eyebrow">TOEGANG EN HERLEIDBAARHEID</p><h1>Auditlog</h1><p class="lead">De laatste 100 handelingen binnen de organisatie.</p><div class="audittable">${rows.map(row=>`<div><time>${fmt(row.created_at)}</time><b>${esc(row.action)}</b><small>${esc(row.user)} · ${esc(row.target_type)}</small></div>`).join("")}</div></section>`,"Audit");bindOrgNav()}catch(error){showError(error)}}
function formCadenceCard(f){return `<article class="listcard"><div><b>${esc(f.title)}</b><small>${esc(f.purpose||"")}</small></div><select class="cadence" data-form="${f.id}" data-prev="${esc(f.cadence)}">${Object.entries(CADENCE_LABELS).map(([v,l])=>`<option value="${v}" ${f.cadence===v?"selected":""}>${l}</option>`).join("")}</select></article>`}
function staffCard(u){return `<article class="listcard"><div><b>${esc(u.email)}</b><small>${u.role==="org_admin"?"Organisatiebeheerder":`${u.assigned_client_ids.length} cliënten toegewezen`}</small></div>${u.role==="caregiver"?`<button class="tiny" data-assign="${u.id}">Toewijzen</button>`:""}</article>`}
async function seedDemo(e){busy(e.target,"Demo vullen…");try{await api("/api/organization/seed-demo",{method:"POST"});organizationManagementPage()}catch(x){showError(x)}}
async function revokeInvite(id){if(!confirm("Deze uitnodigingslink intrekken?"))return;try{await api(`/api/organization/invitations/${id}/revoke`,{method:"POST"});organizationManagementPage()}catch(x){showError(x)}}
async function archiveClient(id){if(!confirm("Cliënt uit het dagelijkse overzicht archiveren? De demo verwijdert het dossier niet definitief."))return;try{await api(`/api/clients/${id}/archive`,{method:"POST"});organizationManagementPage()}catch(x){showError(x)}}
async function resetDemo(){if(!confirm("Alle fictieve cliënten, reminders en het demoformulier archiveren? Documenten en medewerkers blijven bestaan."))return;try{await api("/api/organization/reset-demo",{method:"POST"});organizationManagementPage()}catch(x){showError(x)}}
async function createInvite(){try{const r=await api("/api/organization/invitations",{method:"POST"});const link=`${location.origin}/?join=${r.token}`;shell(`<section class="pad"><button class="back" id="back">‹</button><p class="eyebrow">7 DAGEN GELDIG</p><h1>Uitnodigingslink klaar</h1><p class="lead">Stuur deze link naar medewerkers. Ze worden automatisch lid van ${esc(state.dashboard.organization)}.</p><textarea id="link" readonly>${esc(link)}</textarea><button id="copy">Link kopiëren</button><div class="notice">Je kunt later een nieuwe link maken. Deel deze demo-link niet met onbevoegden.</div></section>`,"Organisatiebeheer");document.querySelector("#back").onclick=organizationDashboard;document.querySelector("#copy").onclick=async()=>{await navigator.clipboard.writeText(link);document.querySelector("#copy").textContent="Gekopieerd ✓"}}catch(x){showError(x)}}
function uploadPage(){shell(`<section class="pad"><button class="back" id="back">‹</button><p class="eyebrow">NAAR PLATFORMADMIN</p><h1>Document uploaden</h1><p class="lead">Upload bijvoorbeeld jullie dagrapportage, intake, zorgplan of incidentformulier. Ruard krijgt direct een signaal.</p><form id="uploadForm"><label>Document<input name="file" type="file" accept=".pdf,.docx,.txt,.json" required></label><label>Wat moet aangepast worden?<textarea name="note" placeholder="Bijvoorbeeld: neem deze verplichte vragen over in onze dagelijkse rapportage"></textarea></label><button>Uploaden</button></form></section>`,"Organisatiebeheer");document.querySelector("#back").onclick=organizationDashboard;document.querySelector("#uploadForm").onsubmit=async e=>{e.preventDefault();const button=e.submitter;busy(button,"Uploaden…");try{await api("/api/organization/documents",{method:"POST",body:new FormData(e.target)});organizationDashboard()}catch(x){showError(x);button.disabled=false;button.textContent=button.dataset.old}}}
function addClientPage(){shell(`<section class="pad"><button class="back" id="back">‹</button><h1>Fictieve cliënt toevoegen</h1><form id="clientForm"><label>Naam<input name="display_name" required></label><label>Korte context<textarea name="context"></textarea></label><label>Zorgdoelen, één per regel<textarea name="goals"></textarea></label><button>Toevoegen</button></form></section>`,"Organisatiebeheer");document.querySelector("#back").onclick=organizationDashboard;document.querySelector("#clientForm").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{await api("/api/clients",{method:"POST",body:JSON.stringify({display_name:f.get("display_name"),context:f.get("context"),goals:String(f.get("goals")).split("\n").filter(Boolean)})});organizationDashboard()}catch(x){showError(x)}}}
function addReminderPage(){shell(`<section class="pad"><button class="back" id="back">‹</button><h1>Reminder toevoegen</h1><form id="reminder"><label>Cliënt<select name="client_id"><option value="">Algemeen</option>${state.clients.map(c=>`<option value="${c.id}">${esc(c.display_name)}</option>`).join("")}</select></label><label>Wat moet gebeuren?<input name="title" required></label><label>Toelichting<textarea name="detail"></textarea></label><label>Wanneer?<input name="due_at" type="datetime-local" required></label><label>Prioriteit<select name="priority"><option value="normal">Normaal</option><option value="high">Hoog</option></select></label><button>Opslaan</button></form></section>`,"Organisatiebeheer");document.querySelector("#back").onclick=organizationDashboard;document.querySelector("#reminder").onsubmit=async e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));d.client_id=d.client_id||null;d.assigned_user_id=null;d.due_at=new Date(d.due_at).toISOString();try{await api("/api/reminders",{method:"POST",body:JSON.stringify(d)});organizationDashboard()}catch(x){showError(x)}}}
function assignPage(userId){const worker=state.staff.find(x=>x.id===userId);shell(`<section class="pad"><button class="back" id="back">‹</button><h1>Cliënt toewijzen</h1><p class="lead">${esc(worker.email)}</p>${state.clients.map(c=>`<button class="secondary assign" data-client="${c.id}">${worker.assigned_client_ids.includes(c.id)?"✓ ":""}${esc(c.display_name)}</button>`).join("")}</section>`,"Organisatiebeheer");document.querySelector("#back").onclick=organizationDashboard;document.querySelectorAll(".assign").forEach(b=>b.onclick=async()=>{try{await api("/api/organization/assignments",{method:"POST",body:JSON.stringify({client_id:b.dataset.client,user_id:userId})});organizationDashboard()}catch(x){showError(x)}})}

async function workerDashboard() {
  try {
    [state.clients,state.reminders,state.forms,state.shiftSettings,state.dailyStatus,state.reviewRequests]=await Promise.all([api("/api/clients"),api("/api/reminders"),api("/api/forms").catch(()=>[]),api("/api/organization/shifts"),api("/api/daily-form-status"),api("/api/my/review-requests").catch(()=>[])]);
    const remaining=state.dailyStatus.flatMap(status=>status.required.filter(form=>!status.completed_form_types.includes(form.form_type)).map(form=>({client:state.clients.find(client=>client.id===status.client_id),form:state.forms.find(item=>item.form_type===form.form_type),title:form.title}))).filter(item=>item.client&&item.form);
    const welcome=(state.me.email.split("@")[0]||"medewerker").replace(/[._-]+/g," ");
    shell(`<section class="pad"><div class="roleline"><p class="eyebrow">${state.preview?"MEDEWERKERSDEMO":"MIJN DIENST"}</p>${state.preview?`<button class="tiny" id="exitDemo">Terug naar beheer</button>`:""}</div><h1>Welkom, ${esc(welcome)}</h1><h2>Nog te doen voor deze dag</h2><p class="lead">${remaining.length+state.reviewRequests.length?`${remaining.length+state.reviewRequests.length} taak${remaining.length+state.reviewRequests.length===1?"":"en"} nog afhandelen`:`Alle dagelijkse formulieren zijn gereed.`}</p>${state.reviewRequests.map(item=>`<button class="clientrow reviewtask" data-review-request="${item.id}"><span>?</span><div><b>Aanvulling gevraagd</b><small>${esc(item.client_name)} · ${esc(item.question)}</small></div><i>›</i></button>`).join("")}${remaining.map(item=>`<button class="clientrow" data-due-form="${item.form.id}" data-due-client="${item.client.id}"><span>□</span><div><b>${esc(item.title)}</b><small>${esc(item.client.display_name)}</small></div><i>›</i></button>`).join("")}${state.reminders.map(reminderCard).join("")}<button id="newReport">● Nieuwe dagrapportage <small>Inspreken of typen</small></button><h2>Cliënten onder je hoede</h2>${state.clients.map(c=>`<button class="clientrow" data-client="${c.id}"><span>${initials(c.display_name)}</span><div><b>${esc(c.display_name)}</b><small>${c.goals.length} actieve zorgdoelen</small></div><i>›</i></button>`).join("")||`<p class="muted">Nog geen cliënten toegewezen.</p>`}<h2>Formulieren</h2><details class="formstore"><summary>Alle beschikbare formulieren (${state.forms.length})</summary>${state.forms.map(formRow).join("")||`<p class="muted">Geen formulieren beschikbaar.</p>`}</details>${!state.preview?`<button class="secondary" id="logout">Uitloggen</button>`:""}</section>`,state.preview?"Medewerkersdemo":"Vandaag");
    document.querySelector(".roleline").insertAdjacentHTML("beforeend",`<button class="tiny" id="employeeSettings">Instellingen</button>`);document.querySelector("#employeeSettings").onclick=employeeSettingsPage;document.querySelector("#exitDemo")?.addEventListener("click",()=>{state.preview=false;history.replaceState({},"","/");organizationDashboard()});document.querySelector("#newReport").onclick=()=>{state.targetForm=null;chooseClient()};document.querySelectorAll("[data-client]").forEach(b=>b.onclick=()=>clientPage(b.dataset.client));document.querySelectorAll("[data-form]").forEach(b=>b.onclick=()=>chooseClientForForm(b.dataset.form));document.querySelectorAll("[data-review-request]").forEach(b=>b.onclick=()=>employeeReviewRequestPage(b.dataset.reviewRequest));document.querySelectorAll("[data-due-form]").forEach(b=>b.onclick=()=>{state.targetForm=state.forms.find(form=>form.id===b.dataset.dueForm);state.client=state.clients.find(client=>client.id===b.dataset.dueClient);continueFormFlow()});document.querySelectorAll("[data-complete]").forEach(b=>b.onclick=async()=>{await api(`/api/reminders/${b.dataset.complete}/complete`,{method:"POST"});workerDashboard()});document.querySelector("#logout")?.addEventListener("click",logout);
  } catch(x){showError(x)}
}
function employeeReviewRequestPage(id){const item=state.reviewRequests.find(review=>review.id===id);if(!item)return; shell(`<section class="pad"><button class="back" id="back">‹</button><p class="eyebrow">AANVULLING GEVRAAGD · ${esc(item.client_name)}</p><h1>Beantwoord de controlevraag</h1><div class="questioncard"><b>Vraag van je organisatie</b><p>${esc(item.question)}</p>${item.due_at?`<small>Gewenst voor ${fmt(item.due_at)}</small>`:""}</div><details class="source-record"><summary>Bekijk je oorspronkelijke rapportage</summary><p>${esc(item.report_text).replace(/\n/g,"<br>")}</p><small>Definitief vastgelegd op ${fmt(item.signed_at)}; dit origineel verandert niet.</small></details><form id="addendumForm"><label>Jouw aanvulling<textarea name="text" required placeholder="Leg alleen de gevraagde aanvullende feiten vast..."></textarea></label><button>Aanvulling vastleggen</button></form><div class="integritynote">Je antwoord wordt als apart, gedateerd dossierstuk gekoppeld aan de oorspronkelijke rapportage.</div></section>`,"Aanvulling");document.querySelector("#back").onclick=workerDashboard;document.querySelector("#addendumForm").onsubmit=async event=>{event.preventDefault();const text=new FormData(event.target).get("text");try{await api(`/api/my/review-requests/${id}/addendum`,{method:"POST",body:JSON.stringify({text})});workerDashboard()}catch(error){showError(error)}}}
function formRow(f){return `<button class="clientrow formrow" data-form="${f.id}"><span>▤</span><div><b>${esc(f.title)}</b><small>${esc(CADENCE_LABELS[f.cadence]||"")}${f.purpose?` · ${esc(f.purpose)}`:""}</small></div><i>›</i></button>`}
function fieldInput(fl){const name=`f_${esc(fl.id)}`;const req=fl.required?"required":"";
  if(fl.type==="textarea")return `<textarea name="${name}" ${req}></textarea>`;
  if(fl.type==="select")return `<select name="${name}" ${req}><option value="">— kies —</option>${(fl.options||[]).map(o=>`<option>${esc(o)}</option>`).join("")}</select>`;
  if(fl.type==="multiselect")return `<div class="multi">${(fl.options||[]).map(o=>`<label class="minicheck"><input type="checkbox" name="${name}" value="${esc(o)}"><span>${esc(o)}</span></label>`).join("")}</div>`;
  if(fl.type==="boolean")return `<label class="minicheck"><input type="checkbox" name="${name}"><span>Ja</span></label>`;
  if(fl.type==="date")return `<input type="date" name="${name}" ${req}>`;
  if(fl.type==="datetime")return `<input type="datetime-local" name="${name}" ${req}>`;
  if(fl.type==="number")return `<input type="number" name="${name}" ${req}>`;
  return `<input type="text" name="${name}" ${req}>`;}
function formFillPage(id){const f=state.forms.find(x=>x.id===id);if(!f)return;const s=f.schema||{};const sections=s.sections||[];
  shell(`<section class="pad"><button class="back" id="back">‹</button><p class="eyebrow">${esc(CADENCE_LABELS[f.cadence]||"FORMULIER")}</p><h1>${esc(f.title)}</h1>${f.purpose?`<p class="lead">${esc(f.purpose)}</p>`:""}<form id="formfill"><label>Cliënt<select name="client_id">${state.client?"":`<option value="">Algemeen (geen cliënt)</option>`}${state.clients.map(c=>`<option value="${c.id}" ${state.client&&state.client.id===c.id?"selected":""}>${esc(c.display_name)}</option>`).join("")}${state.client?`<option value="">Algemeen (geen cliënt)</option>`:""}</select></label>${sections.map(sec=>`<article class="formsection"><h3>${esc(sec.title||"")}</h3>${(sec.fields||[]).map(fl=>`<label class="formfield fill"><b>${esc(fl.label||fl.id)}${fl.required?' <em>*</em>':''}</b>${fieldInput(fl)}</label>`).join("")}</article>`).join("")||`<p class="muted">Dit formulier heeft nog geen velddefinitie.</p>`}<button>Formulier opslaan</button></form></section>`,"Formulier invullen");
  document.querySelector("#back").onclick=workerDashboard;
  document.querySelector("#formfill").onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.target);const answers={};sections.forEach(sec=>(sec.fields||[]).forEach(fl=>{const nm=`f_${fl.id}`;if(fl.type==="multiselect")answers[fl.id]=fd.getAll(nm);else if(fl.type==="boolean")answers[fl.id]=e.target.querySelector(`[name="${nm}"]`)?.checked||false;else answers[fl.id]=fd.get(nm)||"";}));const button=e.submitter;busy(button,"Opslaan…");try{await api(`/api/forms/${id}/submit`,{method:"POST",body:JSON.stringify({client_id:fd.get("client_id")||null,answers,human_review_confirmed:true})});formDonePage(f)}catch(x){showError(x);button.disabled=false;button.textContent=button.dataset.old}}}
function formDonePage(f){shell(`<section class="pad done"><div class="ok">✓</div><h1>${esc(f.title)} opgeslagen</h1><p class="lead">Het handmatig ingevulde formulier is vastgelegd en gelogd.</p><button id="again">Terug naar vandaag</button></section>`,"Gereed");document.querySelector("#again").onclick=workerDashboard}
async function viewSubmissionPage(id){try{const sub=await api(`/api/submissions/${id}`);const form=state.forms.find(f=>f.form_type===sub.form_type);const labels={};if(form&&form.schema)(form.schema.sections||[]).forEach(sec=>(sec.fields||[]).forEach(fl=>labels[fl.id]=fl.label||fl.id));const entries=Object.entries(sub.answers||{});const show=v=>Array.isArray(v)?(v.join(", ")||"—"):v===true?"Ja":v===false?"Nee":(v||"—");shell(`<section class="pad"><button class="back" id="back">‹</button><p class="eyebrow">INGEVULD FORMULIER · ${fmt(sub.created_at)}</p><h1>${esc(sub.form_title)}</h1>${entries.map(([k,v])=>`<div class="formfield"><b>${esc(labels[k]||k)}</b><small>${esc(show(v))}</small></div>`).join("")||`<p class="muted">Geen antwoorden ingevuld.</p>`}</section>`,"Formulier");document.querySelector("#back").onclick=()=>state.client?clientPage(state.client.id):workerDashboard()}catch(x){showError(x)}}
function suggestedForms(p,choose=true){if(state.selectedSuggestionSession!==state.session){state.selectedSuggestedForms=[];state.selectedSuggestionSession=state.session;}if(!p.suggested_forms?.length)return "";return `<div class="suggest"><b>⑃ Mogelijk aanvullend formulier</b>${p.suggested_forms.map(s=>`<label class="suggestrow ${esc(s.urgency||"normal")}">${choose?`<input type="checkbox" data-suggest-form="${esc(s.form_type)}" ${state.selectedSuggestedForms.includes(s.form_type)?"checked":""}>`:""}<span><b>${esc(s.title)}</b><small>${esc(s.reason)}</small></span></label>`).join("")}<small class="muted">Dit is alleen een signaal. Jij beslist volgens protocol; de AI opent of verstuurt niets.</small></div>`}
app.addEventListener("change",event=>{if(event.target.matches("[data-suggest-form]"))state.selectedSuggestedForms=[...document.querySelectorAll("[data-suggest-form]:checked")].map(item=>item.dataset.suggestForm);});
function reminderCard(r){return `<article class="reminder ${r.priority}"><span>${r.priority==="high"?"!":"✓"}</span><div><b>${esc(r.title)}</b><small>${r.client_name?`${esc(r.client_name)} · `:""}${fmt(r.due_at)}</small><p>${esc(r.detail)}</p></div><button class="tiny" data-complete="${r.id}">Gereed</button></article>`}
const initials=name=>name.split(" ").map(x=>x[0]).slice(0,2).join("").toUpperCase();
async function clientPage(id){state.client=state.clients.find(c=>c.id===id);let subs=[];try{subs=await api(`/api/clients/${id}/submissions`)}catch{}shell(`<section class="pad"><button class="back" id="back">‹</button><div class="profile"><span>${initials(state.client.display_name)}</span><div><h1>${esc(state.client.display_name)}</h1><p>Fictieve cliënt</p></div></div><button id="report">＋ Nieuwe rapportage</button><h2>Actieve zorgdoelen</h2>${state.client.goals.map(g=>`<article class="goalcard"><b>◎ ${esc(g.title)}</b><small>AI mag koppeling voorstellen; medewerker beslist.</small></article>`).join("")}<h2>Ingevulde formulieren</h2>${subs.length?subs.map(s=>`<button class="clientrow" data-sub="${s.id}"><span>▤</span><div><b>${esc(s.form_title)}</b><small>${fmt(s.created_at)}</small></div><i>›</i></button>`).join(""):`<p class="muted">Nog geen formulieren ingevuld voor deze cliënt.</p>`}</section>`,"Cliënt");document.querySelector("#back").onclick=workerDashboard;document.querySelector("#report").onclick=narrativePage;document.querySelectorAll("[data-sub]").forEach(b=>b.onclick=()=>viewSubmissionPage(b.dataset.sub))}
function chooseClient(){if(state.clients.length===1){state.client=state.clients[0];return narrativePage()}shell(`<section class="pad"><button class="back" id="back">‹</button><h1>Kies cliënt</h1>${state.clients.map(c=>`<button class="secondary choose" data-id="${c.id}">${esc(c.display_name)}</button>`).join("")}</section>`,"Nieuwe rapportage");document.querySelector("#back").onclick=workerDashboard;document.querySelectorAll(".choose").forEach(b=>b.onclick=()=>{state.client=state.clients.find(c=>c.id===b.dataset.id);narrativePage()})}
function chooseClientForForm(formId){state.targetForm=state.forms.find(form=>form.id===formId);if(!state.targetForm)return;if(state.clients.length===1){state.client=state.clients[0];return continueFormFlow()}shell(`<section class="pad"><button class="back" id="back">‹</button><p class="eyebrow">${esc(state.targetForm.title)}</p><h1>Voor welke cliënt?</h1>${state.clients.map(client=>`<button class="secondary choose" data-id="${client.id}">${esc(client.display_name)}</button>`).join("")}</section>`,"Formulier starten");document.querySelector("#back").onclick=workerDashboard;document.querySelectorAll(".choose").forEach(button=>button.onclick=()=>{state.client=state.clients.find(client=>client.id===button.dataset.id);continueFormFlow()})}
function continueFormFlow(){if(state.me.form_mode==="ai")return targetedNarrativePage();if(state.me.form_mode==="manual")return formFillPage(state.targetForm.id);formModeChoicePage()}
function formModeChoicePage(){shell(`<section class="pad"><button class="back" id="back">‹</button><p class="eyebrow">${esc(state.client.display_name)} · ${esc(state.targetForm.title)}</p><h1>Hoe wil je dit formulier invullen?</h1><button id="chooseAI">Concept maken met AI<small>Inspreken of vrij typen; daarna controleren</small></button><button class="secondary" id="chooseManual">Formulier zelf invullen<small>Alle velden rechtstreeks invullen</small></button><label class="check"><input id="rememberMode" type="checkbox"><span><b>Onthoud mijn keuze</b><small>Je kunt dit later wijzigen via Instellingen.</small></span></label></section>`,"Kies werkwijze");document.querySelector("#back").onclick=workerDashboard;document.querySelector("#chooseAI").onclick=()=>selectFormMode("ai",targetedNarrativePage);document.querySelector("#chooseManual").onclick=()=>selectFormMode("manual",()=>formFillPage(state.targetForm.id))}
async function selectFormMode(mode,next){if(document.querySelector("#rememberMode")?.checked){try{const result=await api("/api/me/form-mode",{method:"POST",body:JSON.stringify({form_mode:mode})});state.me.form_mode=result.form_mode}catch(error){return showError(error)}}next()}
function employeeSettingsPage(){const mode=state.me.form_mode||"ask";shell(`<section class="pad"><button class="back" id="back">‹</button><p class="eyebrow">MEDEWERKERSINSTELLINGEN</p><h1>Formulieren invullen</h1><p class="lead">Kies wat er standaard gebeurt nadat je een formulier en cliënt hebt gekozen.</p><form id="modeSettings"><label>Mijn voorkeur<select name="form_mode"><option value="ask" ${mode==="ask"?"selected":""}>Altijd eerst vragen</option><option value="ai" ${mode==="ai"?"selected":""}>Direct concept maken met AI</option><option value="manual" ${mode==="manual"?"selected":""}>Direct zelf invullen</option></select></label><button>Instelling opslaan</button></form></section>`,"Instellingen");document.querySelector("#back").onclick=workerDashboard;document.querySelector("#modeSettings").onsubmit=async event=>{event.preventDefault();const form_mode=new FormData(event.target).get("form_mode");try{const result=await api("/api/me/form-mode",{method:"POST",body:JSON.stringify({form_mode})});state.me.form_mode=result.form_mode;workerDashboard()}catch(error){showError(error)}}}
function formPreparation(form){const prep=form.preparation||{};const groups=prep.groups||[];const groupHtml=groups.map(group=>`<div class="prepgroup"><b>${esc(group.title)}</b>${group.required?.length?`<ul>${group.required.map(label=>`<li>${esc(label)}</li>`).join("")}</ul>`:""}${group.optional?.length?`<small>Als dit van toepassing is: ${esc(group.optional.join(" · "))}</small>`:""}</div>`).join("");return `<div class="formprep ${esc(prep.complexity||"simple")}"><b>Wat moet je vertellen?</b><p>${esc(prep.intro||form.purpose||"")}</p>${prep.complexity==="detailed"?`<details><summary>Bekijk alle onderwerpen</summary>${groupHtml}</details>`:groupHtml}<small>${esc(prep.instruction||"Beantwoord de punten of vertel vrij in je eigen woorden.")}</small></div>`}
function targetedNarrativePage(){const form=state.targetForm;shell(`<section class="pad"><button class="back" id="back">‹</button><p class="eyebrow">${esc(state.client.display_name)}</p><h1>${esc(form.title)}</h1>${formPreparation(form)}<p class="lead">Spreek of typ vrij. Bekende registratiegegevens worden automatisch ingevuld.</p><button class="voice" id="voice">● Inspreken</button><textarea id="narrative" class="big" placeholder="Beantwoord de punten hierboven of vertel vrij in je eigen woorden…"></textarea><button id="analyse">Concept maken met AI</button><button class="secondary" id="manualFill">Formulier zelf invullen</button><div class="notice">Kies AI voor een concept uit je verhaal, of vul alle velden zelf in. Opslaan kan in beide routes pas na jouw controle.</div></section>`,"Formulier invullen");document.querySelector("#back").onclick=workerDashboard;document.querySelector("#voice").onclick=()=>speech(document.querySelector("#narrative"),document.querySelector("#voice"));document.querySelector("#manualFill").onclick=()=>{stopVoice();formFillPage(form.id)};document.querySelector("#analyse").onclick=()=>{stopVoice();const narrative=document.querySelector("#narrative").value.trim();if(narrative.length<3)return showError(new Error("Vertel eerst wat er gebeurde"));submitNarrative(narrative)}}

function narrativePage(){shell(`<section class="pad"><button class="back" id="back">‹</button><p class="eyebrow">${esc(state.client.display_name)}</p><h1>Hoe is de zorg verlopen?</h1><p class="lead">Spreek of typ gewoon vrij. Bekende gegevens worden direct ingevuld; AI verwerkt alleen de inhoud en mogelijke ontbrekende informatie.</p><button class="voice" id="voice">● Inspreken</button><textarea id="narrative" class="big" placeholder="Bijvoorbeeld: Henk was vanmorgen onrustig en wilde niet mee…"></textarea><div class="notice">Rustige dienst? Zeg kort dat het een normale dag was — zonder bijzonderheden wordt er niet onnodig doorgevraagd.</div><button id="analyse">Concept maken</button><details><summary>Wat gebeurt automatisch?</summary><p>Cliënt, datum, medewerker en dienst komen uit de applicatie. AI zet alleen je vrije tekst om naar de dagelijkse formulieren en kan aanvullende formulieren voorstellen; jij beslist.</p></details></section>`,"Dagrapportage");document.querySelector("#back").onclick=()=>{stopVoice();workerDashboard();};document.querySelector("#voice").onclick=()=>speech(document.querySelector("#narrative"),document.querySelector("#voice"));document.querySelector("#analyse").onclick=()=>{stopVoice();const narrative=document.querySelector("#narrative").value.trim();if(narrative.length<3)return showError(new Error("Vertel eerst wat er gebeurde"));submitNarrative(narrative)}}
function analysingPage(narrative){const shift=state.shiftSettings?.active;shell(`<section class="pad"><p class="eyebrow">DIRECT CONCEPT · GEWONE CODE</p><h1>${esc(state.targetForm?.title||"Je rapportage staat al klaar")}</h1><div class="filling"><b>✓ Automatisch ingevuld</b><small>Cliënt: ${esc(state.client.display_name)}</small>${shift?`<small>Dienst: ${esc(shift.current_shift)} → ${esc(shift.next_shift)}</small>`:""}</div><details open class="conceptpreview"><summary>Bronnotitie — direct zichtbaar</summary><p>${esc(narrative)}</p></details><label>Hoeveel minuten zorg heb je besteed?<input id="earlyMinutes" type="number" min="0" max="1440" value="${esc(state.pendingCareMinutes)}" placeholder="minuten"></label><div class="notice"><b>AI verwerkt alleen wat nog interpretatie vraagt…</b><p>Vul ondertussen de zorgtijd in. Eventuele inhoudelijke vragen verschijnen daarna allemaal tegelijk.</p></div><button class="secondary" id="retry" hidden>Opnieuw proberen</button></section>`,"Concept wordt aangevuld");document.querySelector("#earlyMinutes").oninput=e=>state.pendingCareMinutes=e.target.value;document.querySelector("#retry").onclick=()=>submitNarrative(narrative)}
async function submitNarrative(narrative){analysingPage(narrative);try{const r=await api("/api/sessions",{method:"POST",body:JSON.stringify({client_id:state.client.id,narrative,form_id:state.targetForm?.id||null})});state.session=r.session_id;state.plan=r.plan;renderPlan()}catch(x){showError(x);document.querySelector("#retry").hidden=false}}
let voiceRec=null;
function stopVoice(){if(voiceRec)voiceRec.userStop()}
async function speech(el,btn){
  if(voiceRec){voiceRec.userStop();return;}
  if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder)return showError(new Error("Audio-opname wordt niet ondersteund in deze browser"));
  try{
    const stream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true,autoGainControl:true}});
    const preferred=["audio/webm;codecs=opus","audio/webm","audio/mp4"].find(type=>MediaRecorder.isTypeSupported(type));
    const recorder=new MediaRecorder(stream,preferred?{mimeType:preferred}:undefined);
    const chunks=[];let stopped=false;let timer;
    const reset=()=>{clearTimeout(timer);stream.getTracks().forEach(track=>track.stop());voiceRec=null;btn.classList.remove("recording");btn.disabled=false;btn.textContent="● Inspreken";};
    recorder.ondataavailable=event=>{if(event.data.size)chunks.push(event.data);};
    recorder.onerror=()=>{reset();showError(new Error("De audio-opname is mislukt"));};
    recorder.onstop=async()=>{
      if(!chunks.length){reset();return showError(new Error("Er is geen audio opgenomen"));}
      btn.disabled=true;btn.textContent="Spraak nauwkeurig omzetten…";
      const type=recorder.mimeType||preferred||"audio/webm";
      const extension=type.includes("mp4")?"m4a":"webm";
      const body=new FormData();body.append("file",new Blob(chunks,{type}),`spraak.${extension}`);
      try{const result=await api("/api/transcribe",{method:"POST",body});const base=el.value.trim();el.value=[base,result.text].filter(Boolean).join(base?" ":"");el.focus();}
      catch(error){showError(error);}
      finally{reset();}
    };
    voiceRec={userStop:()=>{if(stopped)return;stopped=true;if(recorder.state==="recording")recorder.stop();}};
    recorder.start(1000);timer=setTimeout(()=>voiceRec?.userStop(),5*60*1000);
    btn.classList.add("recording");btn.textContent="■ Stoppen en tekst maken";
  }catch(error){voiceRec=null;showError(new Error(error.name==="NotAllowedError"?"Geen toegang tot de microfoon":"Inspreken kon niet starten"));}
}
function signals(p){return `${p.risk_level!=="none"?`<div class="alert ${p.risk_level}"><strong>${p.risk_level==="urgent"?"⚠ Direct aandacht nodig":"⚑ Menselijke beoordeling"}</strong><p>${esc(p.short_safety_message||"Volg het organisatieprotocol.")}</p></div>`:""}${(p.legal_signals||[]).map(s=>`<details><summary>${esc(s.title)}</summary><p>${esc(s.rationale)}</p><small>${esc(s.source)} · ${esc(s.human_action)}</small></details>`).join("")}`}
function fillingHeader(p){if(!p.form_drafts?.length)return "";const missing=p.form_drafts.reduce((n,fd)=>n+(fd.fields||[]).filter(f=>f.status==="needs_input").length,0);return `<div class="filling"><b>▤ Bezig met invullen</b><small>${p.form_drafts.map(fd=>esc(fd.title)).join(" · ")}</small>${missing?`<small class="muted">${missing} verplicht veld(en) nog nodig</small>`:`<small class="muted">Verplichte velden compleet</small>`}</div>`}
function appManagedField(fl){return ["time_spent","care_minutes","review_confirmed","human_confirmation"].includes(fl.field_id)||fl.value==="Wordt bij de eindcontrole ingevuld"}
function friendlyFieldValue(value){return value===true||value==="true"?"Ja":value===false||value==="false"?"Nee":value||""}
function formDraftsEditor(p){if(!p.form_drafts?.length)return "";return `<h2>Ingevulde formulieren</h2><p class="muted">De AI vulde deze in op basis van je verhaal. Controleer en pas aan; onbekende of ontbrekende verplichte velden zijn gemarkeerd.</p>${p.form_drafts.map(fd=>`<article class="draftform" data-ftype="${esc(fd.form_type)}"><h3>${esc(fd.title)}</h3>${(fd.fields||[]).map(fl=>{const managed=appManagedField(fl);return `<label class="formfield fill ${fl.status==="needs_input"?"missing":""} ${managed?"managed":""}"><b>${esc(fl.label||fl.field_id)}${managed?' <em class="unk">later automatisch</em>':fl.status==="needs_input"?' <em>ontbreekt</em>':fl.status==="unknown"?' <em class="unk">onbekend</em>':''}</b><textarea data-fid="${esc(fl.field_id)}" ${managed?"readonly":""}>${esc(friendlyFieldValue(fl.value))}</textarea></label>`}).join("")||`<p class="muted">Geen velden ingevuld.</p>`}</article>`).join("")}`}
function formDraftsPreview(p){if(!p.form_drafts?.length)return `<p class="muted">Nog geen formuliervelden beschikbaar.</p>`;return p.form_drafts.map(fd=>`<article class="draftform"><h3>${esc(fd.title)}</h3>${(fd.fields||[]).map(fl=>`<div class="previewfield ${fl.status==="needs_input"?"missing":""}"><b>${esc(fl.label||fl.field_id)}</b><p>${esc(fl.value||"Nog in te vullen")}</p></div>`).join("")}</article>`).join("")}
function renderPlan(){const p=state.plan;if(p.state==="ready")return reviewPage();shell(`<section class="pad question">${signals(p)}${suggestedForms(p)}${fillingHeader(p)}<p class="eyebrow">ÉÉN VRAAG TEGELIJK · AI BEPAALT OF MEER NODIG IS</p><h1>${esc(p.next_question)}</h1><p class="lead">${esc(p.why_this_question)}</p>${p.answer_options?.length?`<div class="options">${p.answer_options.map(o=>`<button class="option" data-value="${esc(o)}">${esc(o)}</button>`).join("")}</div>`:`<textarea id="answer" placeholder="Antwoord alleen wat je weet"></textarea>`}<button class="secondary" id="unknown">Niet bekend</button><button id="next" ${p.answer_options?.length?"disabled":""}>Verder</button><details><summary>Waarom deze vraag?</summary><p>${esc(p.why_this_question)}</p></details></section>`,"AI-verheldering");let answer="";document.querySelectorAll(".option").forEach(b=>b.onclick=()=>{document.querySelectorAll(".option").forEach(x=>x.classList.remove("selected"));b.classList.add("selected");answer=b.dataset.value;document.querySelector("#next").disabled=false});document.querySelector("#unknown").onclick=()=>{answer="Niet bekend";document.querySelector("#next").disabled=false};document.querySelector("#next").onclick=async e=>{answer=answer||document.querySelector("#answer")?.value.trim();if(!answer)return;busy(e.target,"AI denkt verder…");try{const r=await api(`/api/sessions/${state.session}/answer`,{method:"POST",body:JSON.stringify({answer})});state.plan=r.plan;renderPlan()}catch(x){showError(x)}}}
function reviewPage(){const p=state.plan;shell(`<section class="pad">${signals(p)}${suggestedForms(p)}<p class="eyebrow">MENSELIJKE EINDCONTROLE</p><h1>Controleer & sla op</h1><div class="faithful"><b>De AI heeft nooit het laatste woord</b><p>De AI vulde de formulieren in op basis van je verhaal en kan niets opslaan of melden. Bekijk het volledig ingevulde formulier, pas aan waar nodig, en keur zelf goed — pas dan wordt het vastgelegd.</p></div>${formDraftsEditor(p)}<h2>Samenvatting dagrapportage</h2><textarea id="draft" class="big">${esc(p.draft_report)}</textarea><h2>Voorgestelde zorgdoelen</h2>${p.goal_suggestions?.length?p.goal_suggestions.map(g=>`<label class="check"><input type="checkbox" value="${g.goal_id}"><span><b>${esc(g.title)}</b><small>${esc(g.rationale)}</small></span></label>`).join(""):`<p class="muted">Geen koppeling voorgesteld.</p>`}<label>Bestede zorgtijd<input id="minutes" type="number" min="0" max="1440" placeholder="minuten"></label>${p.incident_review_required?`<label class="check alertcheck"><input id="incidentAck" type="checkbox"><span><b>Incidentwaarschuwing zelf beoordeeld</b><small>AI heeft geen melding of juridisch besluit genomen.</small></span></label>`:""}<label class="check"><input id="humanAck" type="checkbox"><span><b>Ik heb de ingevulde formulieren gecontroleerd en keur ze goed</b><small>Opslaan kan pas na jouw goedkeuring. De AI legt nooit zelf vast.</small></span></label><button id="save">Goedkeuren en opslaan</button></section>`,"Controleer & keur goed");document.querySelector("#save").onclick=async()=>{const minutes=Number(document.querySelector("#minutes").value);if(!document.querySelector("#humanAck").checked)return showError(new Error("Bevestig eerst je menselijke controle"));if(!Number.isInteger(minutes)||minutes<0)return showError(new Error("Vul de bestede zorgtijd in"));const goals=[...document.querySelectorAll('.check input[value]:checked')].map(x=>x.value);const form_submissions=[...document.querySelectorAll(".draftform")].map(df=>({form_type:df.dataset.ftype,answers:Object.fromEntries([...df.querySelectorAll("[data-fid]")].map(t=>[t.dataset.fid,t.value]))}));try{await api(`/api/sessions/${state.session}/finalize`,{method:"POST",body:JSON.stringify({report_text:document.querySelector("#draft").value,care_minutes:minutes,selected_goal_ids:goals,form_submissions,incident_review_acknowledged:document.querySelector("#incidentAck")?.checked||false,human_review_confirmed:true})});donePage()}catch(x){showError(x)}}}
function donePage(){const selected=state.selectedSuggestedForms.map(type=>state.forms.find(form=>form.form_type===type)).filter(Boolean);shell(`<section class="pad done"><div class="ok">✓</div><h1>Dagrapportage opgeslagen</h1><p class="lead">De dagelijkse formulieren zijn gecontroleerd en vastgelegd.</p>${selected.length?`<div class="notice"><b>Jij koos nog ${selected.length} aanvullend formulier${selected.length===1?"":"en"}</b><p>Deze zijn niet automatisch ingevuld. Open en controleer ze zelf.</p></div>${selected.map(form=>`<button class="secondary selectedForm" data-form-id="${esc(form.id)}">${esc(form.title)} invullen</button>`).join("")}`:""}<button id="again">Terug naar vandaag</button></section>`,"Gereed");document.querySelectorAll(".selectedForm").forEach(button=>button.onclick=()=>formFillPage(button.dataset.formId));document.querySelector("#again").onclick=()=>{state.session=null;state.plan=null;state.selectedSuggestedForms=[];workerDashboard()}}
async function logout(){await api("/api/logout",{method:"POST"});location.href="/"}
renderPlan=function(){
  const p=state.plan;
  if(p.state==="ready")return reviewPage();
  const questions=(p.clarification_questions?.length?p.clarification_questions:[p.next_question?{id:"question",question:p.next_question,why:p.why_this_question||"",answer_options:p.answer_options||[]}:null]).filter(Boolean);
  const questionHtml=questions.map((q,i)=>`<article class="questionblock"><p class="eyebrow">VRAAG ${i+1} VAN ${questions.length}</p><h2>${esc(q.question)}</h2>${q.why?`<p class="muted">${esc(q.why)}</p>`:""}${q.answer_options?.length?`<select data-question="${esc(q.id)}"><option value="">— kies of typ hieronder —</option>${q.answer_options.map(o=>`<option value="${esc(o)}">${esc(o)}</option>`).join("")}<option value="Niet bekend">Niet bekend</option></select><textarea data-question-extra="${esc(q.id)}" placeholder="Eventuele toelichting"></textarea>`:`<textarea data-question="${esc(q.id)}" placeholder="Antwoord alleen wat je weet"></textarea><button type="button" class="secondary unknownAnswer" data-target="${esc(q.id)}">Niet bekend</button>`}</article>`).join("");
  const current=state.shiftSettings?.active;
  shell(`<section class="pad question">${signals(p)}${suggestedForms(p)}${fillingHeader(p)}${current?`<div class="faithful"><b>${esc(current.current_shift)} → ${esc(current.next_shift)}</b><p>De ontvanger van de overdracht is automatisch bepaald uit de diensten van je werkgever.</p></div>`:""}<details open class="conceptpreview"><summary>Bekijk het concept dat al klaarstaat</summary>${formDraftsPreview(p)}<h3>Samenvatting</h3><p>${esc(p.draft_report||"Nog geen samenvatting beschikbaar.")}</p><small>Je kunt het concept aanpassen zodra alle noodzakelijke informatie compleet is.</small></details><p class="eyebrow">ALLE ONTBREKENDE VRAGEN IN ÉÉN KEER</p><h1>Vul de ontbrekende informatie aan</h1><p class="lead">Eenduidige antwoorden worden direct verwerkt. Alleen als interpretatie nodig is, helpt AI nog één keer.</p>${questionHtml}<button id="next">Antwoorden verwerken</button></section>`,"Concept aanvullen");
  document.querySelectorAll(".unknownAnswer").forEach(b=>b.onclick=()=>{document.querySelector(`[data-question="${CSS.escape(b.dataset.target)}"]`).value="Niet bekend"});
  document.querySelector("#next").onclick=async e=>{const answers=questions.map(q=>{const main=document.querySelector(`[data-question="${CSS.escape(q.id)}"]`);const extra=document.querySelector(`[data-question-extra="${CSS.escape(q.id)}"]`);return {question_id:q.id,value:[main?.value.trim(),extra?.value.trim()].filter(Boolean).join(" — ")}});if(answers.some(a=>!a.value))return showError(new Error("Beantwoord alle vragen of kies ‘Niet bekend’"));busy(e.target,"Antwoorden verwerken…");try{const r=await api(`/api/sessions/${state.session}/answer`,{method:"POST",body:JSON.stringify({answers})});state.plan=r.plan;renderPlan()}catch(x){showError(x);e.target.disabled=false;e.target.textContent=e.target.dataset.old}};
};

const openNarrativePage=narrativePage;
narrativePage=function(){state.targetForm=null;state.pendingCareMinutes="";openNarrativePage();};

function employerFormValue(value){if(Array.isArray(value))return value.join(", ")||"—";return friendlyFieldValue(value)||"—"}
function employerSubmission(form){return `<details class="employerform"><summary><span><b>${esc(form.title)}</b><small>${form.filled} ingevuld${form.empty?` · ${form.empty} leeg`:""}</small></span><i>Bekijk formulier</i></summary><div>${form.fields.map(field=>`<div class="recordfield ${field.empty?"empty":""}"><b>${esc(field.label)}</b><p>${esc(employerFormValue(field.value))}</p></div>`).join("")}</div></details>`}
organizationDashboard=async function(){try{const workspace=await api("/api/organization/workspace");state.orgWorkspace=workspace;const urgent=[...workspace.reviews.filter(item=>item.status==="answered").map(item=>({kind:"review",item})),...workspace.missing_daily.map(item=>({kind:"missing",item}))];shell(`<section class="pad orgshell">${orgNav("overview")}<div class="orgtitle"><div><p class="eyebrow">WERKGEVERSDOSSIER</p><h1>Goedemiddag</h1><p class="lead">Controle, voortgang en openstaand werk van vandaag.</p></div></div><div class="metrics employerMetrics"><article><b>${workspace.metrics.reports_today}</b><span>Rapportages</span><small>${workspace.metrics.care_minutes_today} zorgminuten</small></article><article><b>${workspace.metrics.forms_today}</b><span>Formulieren</span><small>${workspace.metrics.missing_daily} nog nodig</small></article><article><b>${workspace.metrics.answers_to_review}</b><span>Te beoordelen</span><small>${workspace.metrics.overdue_questions} verzoeken verlopen</small></article></div><section class="workpanel"><div class="sectionhead"><h2>Actie nodig</h2><button class="tiny" id="allReviews">Alle controles</button></div>${urgent.length?urgent.slice(0,8).map(entry=>entry.kind==="review"?reviewRow(entry.item):`<button class="workrow" data-org-client="${entry.item.client_id}"><span class="statusdot open"></span><div><b>${esc(entry.item.client_name)}</b><small>${entry.item.count} dagelijks formulier${entry.item.count===1?"":"en"} ontbreekt</small><p>${esc(entry.item.missing_forms.join(" · "))}</p></div><i>›</i></button>`).join(""):`<p class="emptystate">Geen directe controleactie nodig.</p>`}</section>${workspace.reviews.some(item=>item.status==="open")?`<section class="workpanel"><h2>Wacht op medewerker</h2>${workspace.reviews.filter(item=>item.status==="open").slice(0,5).map(reviewRow).join("")}</section>`:""}<section class="workpanel"><div class="sectionhead"><h2>Recente definitieve rapportages</h2><button class="tiny" id="allClients">Naar cliëntdossiers</button></div>${workspace.recent_reports.slice(0,8).map(reportRow).join("")||`<p class="emptystate">Nog geen definitieve rapportages.</p>`}</section></section>`,"Werkgeversportaal");bindOrgNav();document.querySelector("#allReviews").onclick=organizationReviewsPage;document.querySelector("#allClients").onclick=organizationClientsPage;document.querySelectorAll("[data-report]").forEach(button=>button.onclick=()=>organizationReportPage(button.dataset.report));document.querySelectorAll("[data-org-client]").forEach(button=>button.onclick=()=>organizationClientTimelinePage(button.dataset.orgClient));}catch(error){showError(error)}};
organizationReportPage=async function(id){try{const report=await api(`/api/organization/reports/${id}`);const totalFields=report.submissions.reduce((sum,form)=>sum+form.filled+form.empty,0);const emptyFields=report.submissions.reduce((sum,form)=>sum+form.empty,0);shell(`<section class="pad orgshell"><button class="back" id="back">‹</button><div class="recordhead"><div><p class="eyebrow">DEFINITIEF · ${fmt(report.signed_at)}</p><h1>Rapportage ${esc(report.client_name)}</h1><p>${esc(report.author)}${report.care_minutes!=null?` · ${report.care_minutes} minuten`:""}</p></div><span class="locked">🔒 Onveranderlijk</span></div><div class="recordcheck"><div><b>${report.submissions.length}</b><small>gekoppelde formulieren</small></div><div><b>${totalFields-emptyFields}/${totalFields}</b><small>velden ingevuld</small></div><div><b>${report.reviews.filter(item=>item.status!=="closed").length}</b><small>open controles</small></div></div><h2>Samenvatting</h2><article class="recordbody">${esc(report.report_text).replace(/\n/g,"<br>")}</article><section class="forminspection"><div class="sectionhead"><h2>Vastgelegde formulieren</h2><small>Gegevens uit dezelfde rapportagesessie</small></div>${report.submissions.map(employerSubmission).join("")||`<p class="emptystate">Geen gekoppelde formuliervelden gevonden.</p>`}</section><section class="reviewhistory"><div class="sectionhead"><h2>Controle en aanvullingen</h2><button class="tiny" id="askAddition">Gerichte aanvulling vragen</button></div>${report.reviews.map(review=>`<article class="reviewitem"><div><b>${esc(review.question)}</b><small>${fmt(review.created_at)} · ${review.status==="open"?"wacht op medewerker":review.status==="answered"?"antwoord ontvangen":"afgerond"}</small></div>${review.addendum?`<blockquote>${esc(review.addendum)}</blockquote>`:""}${review.status==="answered"?`<button class="tiny" data-close-review="${review.id}">Beoordeeld en afronden</button>`:""}</article>`).join("")||`<p class="emptystate">Geen controlevragen of aanvullingen.</p>`}</section><div class="integritynote"><b>Controle zonder herschrijven</b><p>Het definitieve verslag blijft staan. Nieuwe informatie wordt als gedateerde aanvulling toegevoegd.</p></div></section>`,"Dossiercontrole");document.querySelector("#back").onclick=()=>organizationClientTimelinePage(report.client_id);document.querySelector("#askAddition").onclick=()=>requestAdditionPage(report);document.querySelectorAll("[data-close-review]").forEach(button=>button.onclick=async()=>{await api(`/api/organization/reviews/${button.dataset.closeReview}/close`,{method:"POST"});organizationReportPage(id)});}catch(error){showError(error)}};

// Rustige portalen: kerninformatie eerst, details pas na een bewuste keuze.
orgNav=function(active){const actionCount=(state.orgWorkspace?.metrics?.answers_to_review||0)+(state.orgWorkspace?.metrics?.missing_daily||0);const items=[["overview","Overzicht"],["clients","Cliënten"],["reviews",`Controle${actionCount?` <span class="navbadge">${actionCount}</span>`:""}`],["management","Beheer"],["audit","Audit"]];return `<nav class="orgnav">${items.map(([id,label])=>`<button class="${active===id?"active":""}" data-org-page="${id}">${label}</button>`).join("")}</nav>`};

createInvite=function(){shell(`<section class="pad orgshell"><button class="back" id="back">‹</button><p class="eyebrow">NIEUWE MEDEWERKER</p><h1>Nodig een medewerker uit</h1><p class="lead">Maak een persoonlijke link. Het medewerkernummer wordt automatisch aangemaakt en de link werkt één keer.</p><form id="inviteForm"><label>Naam medewerker<input name="employee_name" required placeholder="Voor- en achternaam"></label><label>Werk-e-mailadres <small>(optioneel)</small><input name="email" type="email" placeholder="naam@organisatie.nl"></label><button>Persoonlijke uitnodiging maken</button></form></section>`,"Medewerker uitnodigen");document.querySelector("#back").onclick=organizationManagementPage;document.querySelector("#inviteForm").onsubmit=async event=>{event.preventDefault();const values=Object.fromEntries(new FormData(event.target));values.email=values.email||null;const button=event.submitter;busy(button,"Uitnodiging maken…");try{const result=await api("/api/organization/invitations",{method:"POST",body:JSON.stringify(values)});const link=`${location.origin}/?join=${result.token}`;shell(`<section class="pad orgshell"><button class="back" id="back">‹</button><div class="successmark">✓</div><p class="eyebrow">UITNODIGING KLAAR</p><h1>${esc(result.employee_name)} kan starten</h1><div class="identitycard"><span>${initials(result.employee_name)}</span><div><b>${esc(result.employee_name)}</b><small>Medewerkernummer ${esc(result.employee_number)}</small></div></div><label>Persoonlijke activatielink<textarea id="link" readonly>${esc(link)}</textarea></label><button id="copy">Link kopiëren</button><p class="privacy">De link is zeven dagen geldig en kan één keer worden gebruikt.</p></section>`,"Medewerker uitnodigen");document.querySelector("#back").onclick=organizationManagementPage;document.querySelector("#copy").onclick=async()=>{await navigator.clipboard.writeText(link);document.querySelector("#copy").textContent="Gekopieerd ✓"}}catch(error){showError(error);button.disabled=false;button.textContent=button.dataset.old}}};

organizationManagementPage=async function(){try{[state.clients,state.reminders,state.staff,state.documents,state.invitations,state.forms,state.shiftSettings]=await Promise.all([api("/api/clients"),api("/api/reminders"),api("/api/organization/staff"),api("/api/organization/documents"),api("/api/organization/invitations"),api("/api/organization/forms").catch(()=>[]),api("/api/organization/shifts")]);const invites=state.invitations.filter(item=>!item.revoked&&!item.expired&&!item.uses);shell(`<section class="pad orgshell">${orgNav("management")}<div class="pageintro"><div><p class="eyebrow">ORGANISATIE</p><h1>Beheer</h1><p class="lead">Medewerkers, formulieren en instellingen op één rustige plek.</p></div><button class="compactaction" id="invite">＋ Nodig medewerker uit</button></div><div class="managementtiles"><button id="staffPanel"><b>${state.staff.filter(item=>item.role==="caregiver").length}</b><span>Medewerkers</span></button><button id="invitePanel"><b>${invites.length}</b><span>Open uitnodigingen</span></button><button id="formsPanel"><b>${state.forms.length}</b><span>Formulieren</span></button></div>${invites.length?`<section class="compactpanel" id="invites"><div class="sectionhead"><h2>Open uitnodigingen</h2></div>${invites.map(item=>`<article class="compactrow"><div><b>${esc(item.employee_name)}</b><small>${esc(item.employee_number)}${item.intended_email?` · ${esc(item.intended_email)}`:""} · geldig tot ${fmt(item.expires_at)}</small></div><button class="tiny" data-revoke="${item.id}">Intrekken</button></article>`).join("")}</section>`:""}<details class="managementgroup" id="employees"><summary>Medewerkers en cliënttoewijzing <span>${state.staff.length}</span></summary>${state.staff.map(staffCard).join("")}</details><details class="managementgroup" id="forms"><summary>Formulieren en gebruiksmoment <span>${state.forms.length}</span></summary><p class="muted">Stel per formulier in wanneer het beschikbaar is.</p>${state.forms.map(formCadenceCard).join("")}</details><details class="managementgroup"><summary>Organisatie-instellingen</summary><div class="actiongrid"><button class="secondary" id="shiftSettings">Diensten</button><button class="secondary" id="formImports">Formulieren importeren</button><button class="secondary" id="upload">Document uploaden</button><button class="secondary" id="workerDemo">Medewerkersweergave</button></div></details><details class="managementgroup"><summary>Demo-inhoud</summary><div class="actiongrid"><button class="secondary" id="addClient">Cliënt toevoegen</button><button class="secondary" id="addReminder">Actie toevoegen</button></div>${!state.clients.length?`<button id="seed">Demo-inhoud toevoegen</button>`:""}<button class="dangerlink" id="reset">Demo-inhoud resetten</button></details></section>`,"Werkgeversportaal");bindOrgNav();document.querySelector("#invite").onclick=createInvite;document.querySelector("#staffPanel").onclick=()=>document.querySelector("#employees").open=true;document.querySelector("#invitePanel").onclick=()=>document.querySelector("#invites")?.scrollIntoView({behavior:"smooth"});document.querySelector("#formsPanel").onclick=()=>document.querySelector("#forms").open=true;document.querySelector("#shiftSettings").onclick=shiftSettingsPage;document.querySelector("#formImports").onclick=formImportsPage;document.querySelector("#upload").onclick=uploadPage;document.querySelector("#workerDemo").onclick=()=>{state.preview=true;history.replaceState({},"","/?demo=employee");workerDashboard()};document.querySelector("#addClient").onclick=addClientPage;document.querySelector("#addReminder").onclick=addReminderPage;document.querySelector("#seed")?.addEventListener("click",seedDemo);document.querySelector("#reset").onclick=resetDemo;document.querySelectorAll("[data-revoke]").forEach(button=>button.onclick=()=>revokeInvite(button.dataset.revoke));document.querySelectorAll("[data-assign]").forEach(button=>button.onclick=()=>assignPage(button.dataset.assign));document.querySelectorAll(".cadence").forEach(select=>select.onchange=async()=>{await api(`/api/organization/forms/${select.dataset.form}/cadence`,{method:"POST",body:JSON.stringify({cadence:select.value})})})}catch(error){showError(error)}};

organizationDashboard=async function(){try{const workspace=await api("/api/organization/workspace");state.orgWorkspace=workspace;const actionCount=workspace.metrics.answers_to_review+workspace.metrics.missing_daily;const waiting=workspace.reviews.filter(item=>item.status==="open").length;shell(`<section class="pad orgshell">${orgNav("overview")}<div class="dashboardhero"><div><p class="eyebrow">VANDAAG</p><h1>Goedemiddag</h1><p>Alles wat aandacht vraagt, in één oogopslag.</p></div><button class="actionbell ${actionCount?"hasactions":""}" id="allReviews" aria-label="Open acties"><span>♟</span>${actionCount?`<b>${actionCount}</b>`:""}</button></div><div class="statstrip"><div><b>${workspace.metrics.reports_today}</b><span>rapportages</span></div><div><b>${workspace.metrics.forms_today}</b><span>formulieren</span></div><div><b>${workspace.metrics.care_minutes_today}</b><span>zorgminuten</span></div></div>${actionCount?`<button class="attentioncard" id="actionCard"><span class="attentionicon">!</span><div><b>${actionCount} ${actionCount===1?"actie vraagt":"acties vragen"} je aandacht</b><small>${workspace.metrics.answers_to_review} te beoordelen · ${workspace.metrics.missing_daily} ontbrekende formulieren</small></div><i>›</i></button>`:`<div class="calmstate"><span>✓</span><div><b>Geen directe acties</b><small>Alles wat nu beoordeeld moet worden is bijgewerkt.</small></div></div>`}${waiting?`<p class="waitingline">⏱ ${waiting} verzoek${waiting===1?"":"en"} wacht${waiting===1?"":"en"} op een medewerker</p>`:""}<section class="workpanel recentcompact"><div class="sectionhead"><h2>Recente rapportages</h2><button class="textbutton" id="allClients">Alle dossiers</button></div>${workspace.recent_reports.slice(0,4).map(reportRow).join("")||`<p class="emptystate">Nog geen definitieve rapportages.</p>`}</section></section>`,"Werkgeversportaal");bindOrgNav();document.querySelector("#allReviews").onclick=organizationReviewsPage;document.querySelector("#actionCard")?.addEventListener("click",organizationReviewsPage);document.querySelector("#allClients").onclick=organizationClientsPage;document.querySelectorAll("[data-report]").forEach(button=>button.onclick=()=>organizationReportPage(button.dataset.report))}catch(error){showError(error)}};

workerDashboard=async function(){try{[state.clients,state.reminders,state.forms,state.shiftSettings,state.dailyStatus,state.reviewRequests]=await Promise.all([api("/api/clients"),api("/api/reminders"),api("/api/forms").catch(()=>[]),api("/api/organization/shifts"),api("/api/daily-form-status"),api("/api/my/review-requests").catch(()=>[])]);const remaining=state.dailyStatus.flatMap(status=>status.required.filter(form=>!status.completed_form_types.includes(form.form_type)).map(form=>({client:state.clients.find(client=>client.id===status.client_id),form:state.forms.find(item=>item.form_type===form.form_type),title:form.title}))).filter(item=>item.client&&item.form);const tasks=remaining.length+state.reviewRequests.length+state.reminders.length;shell(`<section class="pad employeedash"><div class="employeehead"><div><p class="eyebrow">${state.preview?"MEDEWERKERSDEMO":"MIJN DIENST"}</p><h1>Welkom, ${esc(state.me.name||state.me.email.split("@")[0])}</h1>${state.me.employee_number?`<small>${esc(state.me.employee_number)}</small>`:""}</div><button class="settingsicon" id="employeeSettings" aria-label="Instellingen">⚙</button></div><button class="primaryreport" id="newReport"><span>＋</span><div><b>Nieuwe dagrapportage</b><small>Inspreken of typen</small></div><i>›</i></button><section class="employeezone"><div class="sectionhead"><h2>Vandaag</h2>${tasks?`<span class="taskbadge">${tasks}</span>`:`<span class="donebadge">Gereed</span>`}</div>${tasks?`<details class="taskdrawer" ${tasks<=3?"open":""}><summary>${tasks} ${tasks===1?"taak":"taken"} bekijken</summary>${state.reviewRequests.map(item=>`<button class="compacttask" data-review-request="${item.id}"><span>?</span><div><b>Aanvulling gevraagd</b><small>${esc(item.client_name)}</small></div><i>›</i></button>`).join("")}${remaining.map(item=>`<button class="compacttask" data-due-form="${item.form.id}" data-due-client="${item.client.id}"><span>□</span><div><b>${esc(item.title)}</b><small>${esc(item.client.display_name)}</small></div><i>›</i></button>`).join("")}${state.reminders.map(reminderCard).join("")}</details>`:`<div class="calmstate"><span>✓</span><div><b>Je bent bij</b><small>Alle dagelijkse taken zijn afgerond.</small></div></div>`}</section><section class="employeezone"><div class="sectionhead"><h2>Mijn cliënten</h2><small>${state.clients.length}</small></div><div class="clientgrid">${state.clients.map(client=>`<button data-client="${client.id}"><span>${initials(client.display_name)}</span><b>${esc(client.display_name)}</b><small>${client.goals.length} zorgdoelen</small></button>`).join("")||`<p class="emptystate">Nog geen cliënten toegewezen.</p>`}</div></section><button class="formlibrary" id="formLibrary"><span>▤</span><div><b>Formulieren</b><small>Kies uit ${state.forms.length} beschikbare formulieren</small></div><i>›</i></button>${state.preview?`<button class="secondary" id="exitDemo">Terug naar beheer</button>`:`<button class="textbutton logoutlink" id="logout">Uitloggen</button>`}</section>`,state.preview?"Medewerkersdemo":"Vandaag");document.querySelector("#employeeSettings").onclick=employeeSettingsPage;document.querySelector("#newReport").onclick=()=>{state.targetForm=null;chooseClient()};document.querySelector("#formLibrary").onclick=()=>formLibraryPage();document.querySelectorAll("[data-client]").forEach(button=>button.onclick=()=>clientPage(button.dataset.client));document.querySelectorAll("[data-review-request]").forEach(button=>button.onclick=()=>employeeReviewRequestPage(button.dataset.reviewRequest));document.querySelectorAll("[data-due-form]").forEach(button=>button.onclick=()=>{state.targetForm=state.forms.find(form=>form.id===button.dataset.dueForm);state.client=state.clients.find(client=>client.id===button.dataset.dueClient);continueFormFlow()});document.querySelector("#exitDemo")?.addEventListener("click",()=>{state.preview=false;history.replaceState({},"","/");organizationDashboard()});document.querySelector("#logout")?.addEventListener("click",logout)}catch(error){showError(error)}};

function formLibraryPage(){shell(`<section class="pad"><button class="back" id="back">‹</button><p class="eyebrow">FORMULIEREN</p><h1>Wat wil je vastleggen?</h1><p class="lead">Kies een formulier; daarna kies je de cliënt en of je AI wilt gebruiken.</p><div class="librarylist">${state.forms.map(formRow).join("")||`<p class="emptystate">Geen formulieren beschikbaar.</p>`}</div></section>`,"Formulieren");document.querySelector("#back").onclick=workerDashboard;document.querySelectorAll("[data-form]").forEach(button=>button.onclick=()=>chooseClientForForm(button.dataset.form))}

boot();
